score_map = {}
for model in models:
    score_map[model] = (depth_map[model] + breadth_map[model],
                        depth_map[model],
                        breadth_map[model])

# Sort the models based on their score.
sorted_models = sorted(models, key=score_map.get)

# Create a map of model to its index in the sorted list.
index_map = {}
for i, model in enumerate(sorted_models):
    index_map[model] = i

# Sort the models based on their dependencies.
sorted_models = sort_models_dfs(models, model_map, reverse_model_map,
                                index_map)

