Calculate the class balance score for categorical and boolean variables using entropy to calculate a bounded score between 0 and 1. A perfectly uniform distribution would return a score of 0, and a perfectly imbalanced distribution would return a score of 1.
"""
if value_counts.empty:
    return 0

if n_classes == 2:
    return entropy([1, 0], base=2) - entropy(value_counts, base=2)

return entropy(value_counts, base=2) / log2(n_classes)

