def eval_bool(self, expr):
    """
    Evaluate the expression `expr` and return the truthness of its result.
    A result of an expression is said to be true if it contains at least one
    value. It has the same semantics as :func:`bool` on sequences.
    """
    vs = expr.eval(self)
    return bool(vs)


def eval_single(self, expr):

    """
    Evaluate the expression `expr` and return the single result.

    The result of an expression is always an iterable.
    """

def eval_single(self, expr):
    vs = expr.eval(self)
    if len(vs) == 1:
        return vs[0]
    elif len(vs) == 0:
        raise ValueError("Expression returned no results")
    else:
        raise ValueError("Expression returned multiple results")

