import random

from .utils import Markup

def random_word(length: int) -> str:
    word = ""
    for _ in range(length):
        word += chr(random.randint(97, 122))
    return word

def random_sentence(min_words: int, max_words: int) -> str:
    num_words = random.randint(min_words, max_words)
    sentence = ""
    for _ in range(num_words):
        word = random_word(random.randint(4, 10))
        if len(sentence) == 0:
            sentence += word.capitalize()
        else:
            sentence += " " + word
        if random.randint(1, 10) == 1:
            sentence += ","
        if random.randint(1, 10) == 1:
            sentence += "."
    sentence += "."
    return sentence

paragraphs = []
for _ in range(n):
    paragraphs.append(random_sentence(min, max))

if html:
    return Markup("<br>").join(paragraphs)
else:
    return "\n".join(paragraphs)

