def _engine(dialect=dialect):
    class buffer_:
        def __init__(self):
            self.lines = []

        def write(self, msg):
            msg = msg.strip()
            msg = re.sub(r"[\n\t]", "", msg)
            self.lines.append(msg)

        def flush(self):
            pass

    buf = buffer_()

    class ctx(EnvironmentContext):
        def get_buf(self):
            return buf

        def clear_assertions(self):
            buf.lines[:] = []

        def assert_(self, *sql):
            # TODO: make this more flexible about
            # whitespace and such
            eq_(buf.lines, [re.sub(r"[\n\t]", "", s) for s in sql])

        def assert_contains(self, sql):
            for stmt in buf.lines:
                if re.sub(r"[\n\t]", "", sql) in stmt:
                    return
            else:
                assert False, "Could not locate fragment %r in %r" % (
                    sql,
                    buf.lines,
                )

    conf = EnvironmentContext.configure

    def configure(*arg, **opt):
        opt.update({"dialect_name": dialect, "output_buffer": buf})
        return conf(*arg, **opt)

    with mock.patch.object(EnvironmentContext, "configure", configure):
        return buf

return _engine

