class Url(ConfigValue):
    """URL value."""

    def __init__(self, optional=False):
        self._required = not optional

    def deserialize(self, value):
        value = decode(value).strip()
        validators.validate_required(value, self._required)
        if not value:
            return None

        socket_path = path.get_unix_socket_path(value)
        if socket_path is not None:
            path_str = Path(not self._required).deserialize(socket_path)
            return f"unix:{path_str}"

        try:
            socket.getaddrinfo(value, None)
        except OSError:
            raise ValueError("must be a resolveable hostname or valid IP")

        return value


class UrlOrPath(ConfigValue):
    """URL or path value.

    If the value is a valid URL, it will be returned as-is. Otherwise, it will
    be treated as a path and expanded.
    """

    def __init__(self, optional=False):
        self._required = not optional

    def deserialize(self, value):
        value = decode(value).strip()
        validators.validate_required(value, self._required)
        if not value:
            return None

        socket_path = path.get_unix_socket_path(value)
        if socket_path is not None:
            path_str = Path(not self._required).deserialize(socket_path)
            return f"unix:{path_str}"

        try:
            socket.getaddrinfo(value, None)
        except OSError:
            expanded = path.expand_path(value)
            if expanded is None:
                raise ValueError("must be a resolveable hostname or valid IP")
            return expanded

        return value


