def merge(left, right):
    if not left or not right:
        return left or right
    if left[-1] < right[0]:
        return left + right
    if right[-1] < left[0]:
        return right + left
    i, j = 0, 0
    merged = []
    while True:
        if left[i] < right[j]:
            merged.append(left[i])
            i += 1
            if i == len(left):
                return merged + right[j:]
        else:
            merged.append(right[j])
            j += 1
            if j == len(right):
                return merged + left[i:]

